import {isScan,scanDefaults,scanFields} from './scan.mjs';
import {OBJECTIVE_TYPES,objectiveTargets} from './mission.mjs';
export const GIMMICK_DESCRIPTIONS={spawn:'즉시 투하되는 진입 좌표 · 블록 없음',terminal:'명령어를 입력하는 시설 컴퓨터',alarm:'구역 깨우기 · 문 거리/지정 타일 생성',wave:'지정 타일에 적 출현',supply:'9칸 보급 컨테이너',extraction:'구조 신호용 탈출 스캔 · 블록 없음',scan:'원형 홀로그램 · 인원 판정 · 연속 단계',trigger:'이 타일 진입으로 이벤트 발생',cargo:'E 1초 · CarryOn 화물 운반',keycard:'보급함 또는 현장에 놓는 ID 키카드',sleeper:'알람에 깨어나는 대기 몹'};
export function gimmickDefaults(type){return ({spawn:{},scan:scanDefaults(),terminal:{commands:[]},alarm:{wake:true,spawnRule:'distance',distance:2,spawnTiles:[],entity:'minecraft:zombie',count:6,waves:1,waveInterval:15,finishRule:'eliminate',duration:45},wave:{entity:'minecraft:zombie',count:6},sleeper:{entity:'minecraft:zombie',count:1},cargo:{objectKey:''},keycard:{containerId:'',keyId:''},supply:{ammoPacks:0,healthPacks:0},extraction:{...scanDefaults(),duration:10,unlockOnObjectives:true},trigger:{}})[type]||{};}
export function createMissionEditor({getProject,commit,modal,field,selectField,esc,uid}){
  function objectiveDialog(id){const p=getProject(),old=p.objectives.find(o=>o.id===id),o=old||{id:uid('goal'),name:'새 임무 목표',type:'scan',targetId:'',command:'',required:true};
    const body=()=>`${field('목표 이름','goalName',o.name,'text','required maxlength="160"')}${selectField('목표 종류','goalType',o.type,Object.entries(OBJECTIVE_TYPES))}<div id="goalTarget"></div><label class="field"><span><input type="checkbox" name="goalRequired" ${o.required?'checked':''}> 필수 목표</span></label><div class="note subtle">화물 운반 목표는 화물을 든 대원이 탈출 지점 근처에 도착하면 완료됩니다. 이벤트로 완료하는 목표는 실행 블록에서 연결하세요.</div>`;
    modal(old?'목표 편집':'목표 추가',body(),data=>commit(p=>{const next={...o,name:data.get('goalName').trim(),type:data.get('goalType'),targetId:data.get('goalTarget')||'',command:data.get('goalCommand')?.trim()||'',required:data.has('goalRequired')};const i=p.objectives.findIndex(q=>q.id===id);if(i<0)p.objectives.push(next);else p.objectives[i]=next;}));
    const type=document.querySelector('[name="goalType"]'),target=document.getElementById('goalTarget');function refresh(){const kind=type.value,items=objectiveTargets(p,kind);target.innerHTML=(kind==='manual'?'<div class="note subtle">이벤트의 ‘임무 목표 완료 처리’ 블록으로 완료하세요.</div>':selectField('목표 대상','goalTarget',o.targetId,items.length?items:[['','먼저 대상 타일·기믹을 배치하세요']]))+(kind==='command'?field('입력할 명령어','goalCommand',o.command,'text','required maxlength="120"'): '');}type.addEventListener('change',refresh);refresh();
  }
  function show(){const p=getProject();modal('임무 목표와 탈출',`${selectField('임무 방식','missionMode',p.missionMode,[['objectives','필수 목표를 완료하고 탈출'],['extract','탈출 자체가 목표']])}<div class="objective-list">${p.objectives.map(o=>`<div class="objective-row"><div><strong>${esc(o.name)}</strong><small>${esc(OBJECTIVE_TYPES[o.type])} · ${o.required?'필수':'선택'}</small></div><button type="button" class="button" data-goal-edit="${esc(o.id)}">편집</button><button type="button" class="icon-button" data-goal-delete="${esc(o.id)}" aria-label="${esc(o.name)} 삭제">×</button></div>`).join('')||'<p>등록된 목표가 없습니다.</p>'}</div><button type="button" class="button full" data-goal-add>＋ 임무 목표 추가</button><div class="note subtle">필수 목표가 모두 완료되면 기본적으로 탈출 장치가 활성화됩니다. 개별 탈출 장치에서 이 동작을 끄고 이벤트로 제어할 수도 있습니다. ‘탈출 자체가 목표’에서는 처음부터 탈출할 수 있습니다.</div>`,data=>commit(p=>p.missionMode=data.get('missionMode')));
    document.querySelector('[name="missionMode"]').addEventListener('change',e=>commit(p=>p.missionMode=e.target.value));
    document.querySelector('[data-goal-add]').onclick=()=>objectiveDialog();document.querySelectorAll('[data-goal-edit]').forEach(b=>b.onclick=()=>objectiveDialog(b.dataset.goalEdit));document.querySelectorAll('[data-goal-delete]').forEach(b=>b.onclick=()=>{commit(p=>p.objectives=p.objectives.filter(o=>o.id!==b.dataset.goalDelete));show();});
  }
  return {show,objectiveDialog};
}
export function gimmickSettings(g,p,{field:f,select:s,esc}){
  const a=g.settings,options=type=>[['','직접 배치 · 없음'],...p.gimmicks.filter(q=>q.type===type).map(q=>[q.id,q.name])],yn=[['true','예'],['false','아니오']],bool=(label,key,def)=>s(label,'settings.'+key,String(a[key]??def),yn);
  let html='';
  if(['wave','sleeper','alarm'].includes(g.type))html+=f('몹 엔티티 ID','settings.entity',a.entity||'minecraft:zombie','text','maxlength="120"')+f(g.type==='alarm'?'대상 타일별 1회 생성 수 · 회당 총 64마리 제한':'생성 수','settings.count',a.count??6,'number','min="1" max="64" step="1"');
  if(g.type==='terminal')html+=`<label class="field">허용 명령어 · 한 줄에 하나<textarea aria-label="허용 명령어 · 한 줄에 하나" data-property="settings.commands" data-value-kind="lines" rows="4" maxlength="8000">${esc((a.commands||[]).join('\n'))}</textarea></label><div class="note subtle">목표·이벤트에 등록한 명령어도 자동 허용합니다. HELP와 STATUS는 기본 제공하며, 서버 명령어를 실행하지 않습니다.</div>`;
  if(g.type==='alarm')html+=bool('지정 구역의 몹 깨우기','wake',true)+s('깨울 구역','settings.wakeRoomId',a.wakeRoomId||'',[['','알람이 속한 구역'],...p.rooms.map(r=>[r.id,r.code+' · '+r.name])])+s('새 몹 생성 규칙','settings.spawnRule',a.spawnRule||'distance',[['distance','현재 타일에서 문 연결 거리'],['tiles','배치된 타일 직접 지정'],['none','새로 생성하지 않음']])+f('문을 건너는 횟수 · 최단 거리','settings.distance',a.distance??2,'number','min="0" max="32" step="1"')+`<label class="field">직접 지정한 생성 타일<select multiple size="5" data-property="settings.spawnTiles" data-value-kind="list" aria-label="직접 지정한 생성 타일">${p.placements.map(q=>`<option value="${esc(q.id)}" ${(a.spawnTiles||[]).includes(q.id)?'selected':''}>${esc(p.rooms.find(r=>r.id===q.roomId)?.code||'?')} / ${esc(q.areaCode)} · ${esc(p.tiles.find(t=>t.id===q.tileId)?.name)}</option>`).join('')}</select><small>여러 타일은 Ctrl/Command를 누르고 선택</small></label>`+f('생성 횟수','settings.waves',a.waves??1,'number','min="1" max="100" step="1"')+f('생성 간격 · 초','settings.waveInterval',a.waveInterval??15,'number','min="1" max="3600" step="1"')+s('알람 종료 조건','settings.finishRule',a.finishRule||'eliminate',[['eliminate','모든 생성 완료 + 대상 몹 처치'],['timer','제한 시간 경과']])+f('제한 시간 · 초','settings.duration',a.duration??45,'number','min="1" max="3600" step="1"')+'<div class="note subtle">거리 기준점은 알람을 발생시킨 이벤트의 타일입니다. 문 연결 두 번의 최단 거리는 2입니다. 이벤트에 타일이 없으면 알람 기믹의 타일을 사용합니다.</div>';
  if(g.type==='keycard')html+=f('키카드 식별 이름','settings.keyId',a.keyId||g.id,'text','maxlength="120"')+s('배치할 보급 컨테이너','settings.containerId',a.containerId||'',options('supply'));
  if(g.type==='cargo')html+=f('화물 식별 이름','settings.objectKey',a.objectKey||g.id,'text','maxlength="120"')+'<div class="note subtle">CarryOn 필요 · 양손을 비우고 E 1초 유지. 내려놓기는 CarryOn의 즉시 배치를 사용합니다.</div>';
  if(g.type==='supply')html+=f('탄약 보급 팩 수량','settings.ammoPacks',a.ammoPacks??0,'number','min="0" max="36" step="1"')+f('체력 보급 팩 수량','settings.healthPacks',a.healthPacks??0,'number','min="0" max="36" step="1"')+'<div class="note subtle">9칸 컨테이너에 팩을 종류별 4개씩 겹쳐 넣습니다. 0은 추가하지 않음입니다. 기존 내용물과 키카드가 사용할 자리도 남겨 주세요. 팩을 들고 E를 1초 유지하면 사용합니다. 모드 0.4.5 이상이 필요합니다.</div>';
  if(isScan(g.type))html+=scanFields(g,p,{field:f,select:s,esc});
  return html;
}
